package ej1;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import ar.edu.unlp.info.oo1.ej1.TweetNormal;
import ar.edu.unlp.info.oo1.ej1.Usuario;

public class UsuarioTest {
	private Usuario usu;
	
	@BeforeEach
	public void setUp() {
		this.usu = new Usuario ("aa");
	}
	
	@Test
	public void postearTest () {
		this.usu.postear("");
		Assertions.assertEquals(0, this.usu.getCantidadDePosts());
		
		
		this.usu.postear("aaaaa");
		Assertions.assertEquals(1, this.usu.getCantidadDePosts());
	}
	
	@Test
	public void repostrarTest () {
		this.usu.repostear(null);
		Assertions.assertEquals(0, this.usu.getCantidadDePosts());
		
		TweetNormal post = new TweetNormal ("eso");
		this.usu.repostear(post);
		Assertions.assertEquals(1, this.usu.getCantidadDePosts());
	}
	
	
}
